module HoennTrainerRematches
  HOENN_DIALOGUE_DATA = [
  {"type" => "YOUNGSTER", "name" => "Charlie", "version" => 0, "default" => "You're great for a newbie! Want to fight again?", "caught" => "I found a cool <CAUGHT_POKEMON> while walking in the tall grass!", "evolved" => "Look! My <UNEVOLVED_POKEMON> evolved into <EVOLVED_POKEMON>! Let me show you how strong it is now!", "fused" => "I bought a DNA Splicer at the Poké Mart and fused my <HEAD_POKEMON> and <BODY_POKEMON>! They're way more powerful together!", "unfused" => "I unfused my <UNFUSED_POKEMON>.<br>I wonder what I can fuse my <HEAD_POKEMON> and <BODY_POKEMON> with next!", "reversed" => "My <UNREVERSED_POKEMON> is way cooler now that I reversed it into a <REVERSED_POKEMON>!", "gift" => "Huh? I found this next to the pond. You can have it, I guess."},
  {"type" => "BUGCATCHER", "name" => "Rick", "version" => 0, "default" => "Battle as many Trainers as you can! That's how we Trainers get stronger!", "caught" => "I added a new <CAUGHT_POKEMON> to my team! Wanna see it?", "evolved" => "Bug Pokémon change a lot when they evolve.<br>Want to see what my <UNEVOLVED_POKEMON> turned into?", "fused" => "I know just what to do to make my team better.<br>I'll fuse my <HEAD_POKEMON> and <BODY_POKEMON>!", "unfused" => "Maybe my <UNFUSED_POKEMON> will be better unfused. What do you think?", "reversed" => "Woah, <REVERSED_POKEMON> looks way stronger than it did as a <UNREVERSED_POKEMON>!", "gift" => "Hey! I caught this item in my net for you!"},
  {"type" => "YOUNGSTER", "name" => "Allen", "version" => 0, "default" => "I'm always down for another battle! I'll beat you one day, I swear!", "caught" => "I just caught a <CAUGHT_POKEMON>! How cool is that?", "evolved" => "Did you know <UNEVOLVED_POKEMON> evolves into <EVOLVED_POKEMON>?<br>Mine just did!", "fused" => "My <HEAD_POKEMON> and <BODY_POKEMON> accidentally touched my last DNA Splicer and became a <FUSED_POKEMON>. Oops.", "unfused" => "I'm going to see what else I can fuse <HEAD_POKEMON> and <BODY_POKEMON> with instead of keeping them as <UNFUSED_POKEMON>.", "reversed" => "Which is better, my old <UNREVERSED_POKEMON> or this new <REVERSED_POKEMON>?<br>We'll find out now!", "gift" => "There you are! I got you a little something to thank you for all these cool battles we've had."},
  {"type" => "LASS", "name" => "Tiana", "version" => 0, "default" => "I need to train more if I want to take on the Gym Challenge.<br>Will you rematch me or trade me one of your strong Pokémon?", "caught" => "I caught a new Pokémon! Meet <CAUGHT_POKEMON>!", "evolved" => "Whew, after training hard, my <UNEVOLVED_POKEMON> finally evolved into <EVOLVED_POKEMON>!", "fused" => "<HEAD_POKEMON> and <BODY_POKEMON> joined strengths and became <FUSED_POKEMON>!", "unfused" => "<HEAD_POKEMON> and <BODY_POKEMON> weren't working out together, so I unfused them.", "reversed" => "<REVERSED_POKEMON> is so much stronger than <UNREVERSED_POKEMON>!", "gift" => "<PLAYER_NAME>! This'll help you to become a good Trainer!"},
  {"type" => "YOUNGSTER", "name" => "Billy", "version" => 0, "default" => "Another match, really? Do you really not mind the sand getting all over the place?", "caught" => "You never know what Pokémon you'll find on the beach!<br>I tripped on a <CAUGHT_POKEMON> while running around, so I took the opportunity to catch it!", "evolved" => "Huff, huff...<br>If you exercise a lot, you'll grow big and strong, just like me and my new <EVOLVED_POKEMON>!", "fused" => "I found a DNA Splicer washed up on the shore, and I used it on <HEAD_POKEMON> and <BODY_POKEMON>!", "unfused" => "My <UNFUSED_POKEMON>? Nah, I unfused it.", "reversed" => "I reversed <REVERSED_POKEMON>. What will its footsteps look like on the sand now?", "gift" => "Ugh, I dropped this item in the sand. I don't want it anymore, so you can have it!"},
  {"type" => "FISHERMAN", "name" => "Darian", "version" => 0, "default" => "Fishing is chill, so I can spare some time for a rematch.", "caught" => "Check out this <CAUGHT_POKEMON> I reeled in this morning!", "evolved" => "My Pokémon ate all my bait and evolved into a <EVOLVED_POKEMON>.", "fused" => "Gah, I fell asleep while fishing...<br>When I woke back up, my <HEAD_POKEMON> and <BODY_POKEMON> were gone!<br>All I could find was this <FUSED_POKEMON>.", "unfused" => "They say there's plenty of fish in the sea...<br>...And there's plenty in my team now that I've unfused my <UNFUSED_POKEMON>!", "reversed" => "I got a little bored waiting for a bite. I reversed my <UNREVERSED_POKEMON> into a <REVERSED_POKEMON> to pass the time.", "gift" => "A Pokémon I fished was holding this. I'd like you to have it!"},
  {"type" => "LADY", "name" => "Cindy", "version" => 0, "default" => "Would you like to see my adorable Pokémon again?", "caught" => "I've met a new friend!<br>Look at this adorable <CAUGHT_POKEMON>!", "evolved" => "Gasp! My <UNEVOLVED_POKEMON>...<br>It became a <EVOLVED_POKEMON>!", "fused" => "Squee! <HEAD_POKEMON> and <BODY_POKEMON> are even prettier fused together!", "unfused" => "Seeing <UNFUSED_POKEMON> got old, so I unfused it into <HEAD_POKEMON> and <BODY_POKEMON>.", "reversed" => "What do you think of my <REVERSED_POKEMON>?<br>Much cuter than my old <UNREVERSED_POKEMON>, right?", "gift" => "It's proper etiquette to give your friends presents. Here you go!"},
  {"type" => "BUGCATCHER", "name" => "Lyle", "version" => 0, "default" => "After catching so many Pokémon, I'm all out of Poké Balls...<br>Can you trade me something better than my bugs?", "caught" => "I caught a <CAUGHT_POKEMON>!<br>My swarm is even bigger now!", "evolved" => "Having a lot of Pokémon won't help if they're puny. That's why I evolved my <UNEVOLVED_POKEMON> into a <EVOLVED_POKEMON>!", "fused" => "Huh? Did <HEAD_POKEMON> and <BODY_POKEMON> fuse when I wasn't looking?!", "unfused" => "I unfused my <UNFUSED_POKEMON>, so now my swarm has even more bugs in it!", "reversed" => "<UNREVERSED_POKEMON>... No...<br><REVERSED_POKEMON> is better!", "gift" => "My Bug Pokémon always bring me items they find in the forest. Have one!"},
  {"type" => "BUGCATCHER", "name" => "James", "version" => 0, "default" => "I wanna see more fusions! Do you want to show me yours?", "caught" => "I caught a <CAUGHT_POKEMON>! Now what should I fuse it with?", "evolved" => "Woah! My <UNEVOLVED_POKEMON> evolved! It should make some even cooler fusions now!", "fused" => "I saw a cool <FUSED_POKEMON> the other day, so I recreated it by fusing my <HEAD_POKEMON> and <BODY_POKEMON>.", "unfused" => "There are so many possible fusions to explore. I unfused <UNFUSED_POKEMON> so that I could test out more combinations!", "reversed" => "Woah, did you know that you can reverse fused Pokémon? I wonder if that happens in the wild too.", "gift" => "<PLAYER_NAME>! Give this to one of your fusions!"},
  {"type" => "RICHBOY", "name" => "Winston", "version" => 0, "default" => "Achoo! My allergies are driving me crazy...", "caught" => "I found a cute <CAUGHT_POKEMON>. I'm not sure if I should keep it or give it to my girlfriend...", "evolved" => "Do you think that my girlfriend will like <UNEVOLVED_POKEMON> better now that it's a <EVOLVED_POKEMON>?", "fused" => "Achoo! I accidentally fused my Pokémon while sneezing!", "unfused" => "I unfused <UNFUSED_POKEMON> because my girlfriend thought it was unsettling. I can't tell if she meant the Pokémon or me...", "reversed" => "I have so many spare DNA Reversers. I used one on my <UNREVERSED_POKEMON> just to see what it would look like as a <REVERSED_POKEMON>.", "gift" => "I got this gift for my girlfriend... But on second thought, I don't know if she'll like it.<br>I suppose you could have it instead."},
  {"type" => "LASS", "name" => "Haley", "version" => 0, "default" => "It's such a breezy day! Perfect for a rematch, don't you think?", "caught" => "A <CAUGHT_POKEMON> flew in on the wind! I caught it!", "evolved" => "Woah, <UNEVOLVED_POKEMON> evolved! Look how strong it is now.", "fused" => "Huh? The wind carried a DNA Splicer. I just had to use it on <HEAD_POKEMON> and <BODY_POKEMON>!", "unfused" => "Whoops! I accidentally unfused <HEAD_POKEMON> and <BODY_POKEMON>!", "reversed" => "Look how silly <UNREVERSED_POKEMON> looks now that it's reversed!", "gift" => "Huh? The wind carried this to me! Do you want it?"},
  {"type" => "TWIN_1", "name" => "Gina", "version" => 0, "default" => "We need to train lots more! We usually battle each other to train, but you're way stronger!", "caught" => "We caught a <CAUGHT_POKEMON> together! We make a great team!", "evolved" => "Mia helped me evolve <UNEVOLVED_POKEMON>. Look at it now!", "fused" => "Me and my twin fused our Pokémon! Now we both share this <FUSED_POKEMON>!", "unfused" => "We kept bickering over our <UNFUSED_POKEMON>, so we unfused it.", "reversed" => "I reversed my <UNREVERSED_POKEMON> into a <REVERSED_POKEMON> because my sister said it would be better... I dunno, was she right?", "gift" => "Heehee! I got you a little gift. But don't tell Mia!"},
  {"type" => "TWIN_2", "name" => "Mia", "version" => 0, "default" => "Maybe if I try without Gina... Will you battle me?", "caught" => "I caught a <CAUGHT_POKEMON> all by myself, without Gina!", "evolved" => "My <UNEVOLVED_POKEMON> evolved! I bet Gina's gonna say it was her idea... But it wasn't! ", "fused" => "Don't tell Gina, but I took my sister's DNA Splicer to make this <FUSED_POKEMON>.", "unfused" => "I unfused my <UNFUSED_POKEMON> before Gina noticed. Shhh, don't snitch!", "reversed" => "I turned my <UNREVERSED_POKEMON> into a <REVERSED_POKEMON> while Gina wasn't looking, hehehe!", "gift" => "Gina got me this gift, but you look like you need it more than I do!"},
  {"type" => "FISHERMAN", "name" => "Ivan", "version" => 0, "default" => "I need to train my fish to fight out of the water! Will you help me out?", "caught" => "I reeled in a new catch! Let's see if it's a keeper or if I should release it!", "evolved" => "Woah! My fish evolved! It's so much bigger now!", "fused" => "I fused <HEAD_POKEMON> and <BODY_POKEMON>. Now they're twice as slippery!", "unfused" => "I unfused <UNFUSED_POKEMON>. Turns out two half-decent swimmers don't always make a great one.", "reversed" => "I got it! My fusion wasn't working out because of the order. So, I reversed <UNREVERSED_POKEMON> into <REVERSED_POKEMON>!", "gift" => "Huh? I found this in the water. Is it yours?"},
  {"type" => "YOUNGSTER", "name" => "Josh", "version" => 0, "default" => "Since you clearly know what you're doing, how about a battle so we Gym Trainers can learn a thing or two?", "caught" => "Gym Leader Roxanne gave me a <CAUGHT_POKEMON>. I want to prove she made the right choice!", "evolved" => "After watching the Gym Leader's amazing battles, my <UNEVOLVED_POKEMON> evolved! Let's see what it can do now!", "fused" => "I fused my <HEAD_POKEMON> and <BODY_POKEMON>. I think they have more potential together!", "unfused" => "Gym Leader Roxanne said I have to master the basics, so I unfused my <UNFUSED_POKEMON>. Let's battle so I can impress my Gym Leader!", "reversed" => "The other Gym Trainers suggested I turn my <UNREVERSED_POKEMON> into its reverse fusion. Battle with me and tell me if my Pokémon is stronger now!", "gift" => "You're so strong, you could be a Gym Trainer too! Take this gift and give it some thought."},
  {"type" => "YOUNGSTER", "name" => "Tommy", "version" => 0, "default" => "Roxanne taught me that you have to work crazy hard to see results. How about it? Let's study up with a battle!", "caught" => "I caught this <CAUGHT_POKEMON>, but it's a bit lazy. Help me teach it how to work hard!", "evolved" => "Roxanne worked so hard on teaching me how to battle that my Pokémon evolved! Have you evolved any of your Pokémon?", "fused" => "My <HEAD_POKEMON> fused with another Pokémon! Maybe it will work twice as hard and be twice as smart!", "unfused" => "Now that my <UNFUSED_POKEMON> unfused, they can both work on different things. We're gonna blow the grading curve!", "reversed" => "My Pokémon thought that reversing would disguise it so I wouldn't make it work hard. I'm gonna have to show <REVERSED_POKEMON> what real work ethic looks like!", "gift" => "You work almost as hard as Roxanne at battling! You should have this since you practice so much."},
  {"type" => "HIKER", "name" => "Marc", "version" => 0, "default" => "Do you want another free lesson?", "caught" => "One of my students gifted me this <CAUGHT_POKEMON> as a token of her appreciation.<br>If I win, will you gift me one of your Pokémon as well?", "evolved" => "It is not just people that evolve through learning and experience. Pokémon do the same!", "fused" => "Fusing two Pokémon is like two students sticking their heads together on a group assignment!", "unfused" => "The group work is over. Everyone, time to work by yourself again!", "reversed" => "Different tasks require different skillsets.<br>That is why sometimes it makes sense to switch up who is in the role of the leader.", "gift" => "I have a gift for you. It's called the blessing of knowledge.<br>...<br>Okay, fine, you can have this too."},
  {"type" => "LEADER_Roxanne", "name" => "Roxanne", "version" => 0, "default" => "Are you going to challenge other Gym Leaders? I can help you train for those battles.", "caught" => "I caught this <CAUGHT_POKEMON> while hunting for stones to research. Together, we can research battles as well.", "evolved" => "Studying at the Trainers' School and applying what I learned to battles here let my <UNEVOLVED_POKEMON> evolve. I'll show you what happens when both Trainer and Pokémon evolve their skills.", "fused" => "Bringing my <HEAD_POKEMON> and <BODY_POKEMON> together to fuse is like bringing together two ideas to reach understanding. I'll show you what that means.", "unfused" => "Don't underestimate the power of strength in numbers. With the help of this DNA Splicer, I now have another rock-solid Pokémon to battle with.", "reversed" => "If I always study with the same team, I won't learn as much about battles. I reversed my <UNREVERSED_POKEMON> to help with that.", "gift" => "Your battling is A+. Take this and let it motivate you to keep learning."},
  {"type" => "BUGCATCHER", "name" => "Jose", "version" => 0, "default" => "One day I want to become a ninja!<br>A ninja that fights with the help of his Bug Pokémon!", "caught" => "My army of Bug Pokémon keeps growing! Swarm attack!", "evolved" => "Hahaha, my <EVOLVED_POKEMON> has grown into a perfectly ultimate great insect!", "fused" => "By themselves, Bug Pokémon are rather weak.<br>That's why I try to build a team with as many of them as possible!", "unfused" => "Strength in numbers! Surprise attack!", "reversed" => "Bet you didn't expect my classic ninja switcheroo!", "gift" => "Here, this has been passed on by the ancestors of my totally legit Ninja Clan for generations."},
  {"type" => "YOUNGSTER", "name" => "Joey", "version" => 0, "default" => "Are you here to hurt me again?!", "caught" => "I got a few bruises catching this <CAUGHT_POKEMON>!", "evolved" => "I was standing a bit too close to my <EVOLVED_POKEMON> when it evolved.<br>Got pushed back and fell into that thorny bush over there.<br>Lesson learned.", "fused" => "Ouch! Who thought it was a good idea to put such a pointy end on a DNA Splicer?!", "unfused" => "I wrapped my DNA Splicer in a paper towel, but I still managed to pierce myself with it...", "reversed" => "Why are the DNA Reversers so pointy?! Ouch!", "gift" => "Here, take this before I find a way to hurt myself with it."},
  {"type" => "SCHOOLGIRL", "name" => "Karen", "version" => 0, "default" => "I have to study harder! Will you help me learn more about Pokémon fusions?", "caught" => "Today's assignment was catching a <CAUGHT_POKEMON>!", "evolved" => "<UNEVOLVED_POKEMON> evolved! I'll get a good grade for sure!", "fused" => "I fused my <HEAD_POKEMON> and <BODY_POKEMON> for a school project!", "unfused" => "DNA Splicers can unsplice fusions! Wait, no... Unfuse? Um... <br>In any case, now my <HEAD_POKEMON> and <BODY_POKEMON> are unfuspliced!", "reversed" => "For show and tell today, I reversed my <UNREVERSED_POKEMON> into a <REVERSED_POKEMON>!<br>Everyone was impressed!", "gift" => "I made this in class yesterday and got a perfect grade! You can have it!"},
  {"type" => "YOUNGSTER", "name" => "Johnson", "version" => 0, "default" => "Can you tell me the way home? I'm a bit lost...", "caught" => "Huh? You are wondering why I am still here?<br>Well, I was taken in by this <CAUGHT_POKEMON> and its family.<br>At first I was a bit scared, but I quickly realized that they were friendly creatures, not at all evil.", "evolved" => "You really don't have to worry about me, you know? Look, I even have a new friend!", "fused" => "Are you hungry? My <FUSED_POKEMON> collected some berries for me.<br>I can share.", "unfused" => "You sure keep coming back to this dead end quite a lot...", "reversed" => "This is still a dead end. If you want to get out of here, you need to reverse.<br>Here, let me show you how it is done.", "gift" => "Thank you for looking out for me. This is for your trouble."},
  {"type" => "HIKER", "name" => "Clark", "version" => 0, "default" => "A rematch? Let's make it quick, though.", "caught" => "My son demanded that I catch this <CAUGHT_POKEMON>.<br>Maybe I will gift it to him once he is a bit older.", "evolved" => "Woah, my <EVOLVED_POKEMON> grew up before my son did!<br>Does that mean that I took better care of it than I did of my son?!", "fused" => "My son watched me fuse this <FUSED_POKEMON>, and now he is obsessed with the idea of fusing himself!<br>I keep telling him that humans cannot fuse, but someone told him a story of a person in the Kanto region who did just that...", "unfused" => "I unfused my <UNFUSED_POKEMON>.<br>Maybe my son will shut up about this fusion stuff now...", "reversed" => "My son loves watching videos of Pokémon fusing and reversing on the internet, so I tried it myself.", "gift" => "If you ever have a child yourself, you will need this."},
  {"type" => "HIKER", "name" => "Devan", "version" => 0, "default" => "What? You are wondering why I am still on this side of the mountain?<br>L-listen, I totally managed to climb over it by now, okay?!", "caught" => "I met this <CAUGHT_POKEMON> on a hike, and we have been traveling together ever since.", "evolved" => "Hah, my <EVOLVED_POKEMON> grew up to be as tall as that mountain over there!<br>Well, almost...", "fused" => "Just like how two tectonic plates fused below us to create that mountain, my <FUSED_POKEMON> fused to reach its summit!", "unfused" => "Rivers erode mountains, even if it takes millenia. Everything must come to an end.", "reversed" => "Once I have climbed the tallest mountain, I will dive down the deepest trench!", "gift" => "Here, I found this at the top of that mountain."},
  {"type" => "SCHOOLBOY", "name" => "Jerry", "version" => 0, "default" => "My assignment was to train up and evolve a Pokémon. Will you help me some more?", "caught" => "I caught a <CAUGHT_POKEMON>. Maybe it'll be easier to evolve!", "evolved" => "I did it! I evolved <UNEVOLVED_POKEMON> into <EVOLVED_POKEMON>! Thanks for helping me with my assignment!", "fused" => "Pokémon evolve faster when they're fused, right? No? So much for this <FUSED_POKEMON>!", "unfused" => "Maybe <UNFUSED_POKEMON> will evolve faster now that it's split in two!", "reversed" => "Does reversing do anything for evolving Pokémon? Anyway, <UNREVERSED_POKEMON> is now a <REVERSED_POKEMON>!", "gift" => "Heheh! I took this from the teacher's office.<br>It's for you!"},
  {"type" => "SCHOOLMATE_SR", "name" => "Janice", "version" => 0, "default" => "Do you have some time to tutor me? I need some help on math.<br>What, you only do Pokémon battling? That's fine too, I guess.", "caught" => "I saw this <CAUGHT_POKEMON>, and it looked very smart! I hope that it will help me study.", "evolved" => "Woah, <EVOLVED_POKEMON> really evolved, just like my teacher said!", "fused" => "My big sister said that she discussed the ethicasies of fusing Pokémon at school.<br>But I don't know what that word means.", "unfused" => "Maybe my <HEAD_POKEMON> becomes sad when it is fused...", "reversed" => "I think I messed something up when taking care of my <BODY_POKEMON> and <HEAD_POKEMON>...", "gift" => "A boy from my class gave me this, but he was stuttering so much that I didn't understand what he was saying.<br>You can have it."},
  {"type" => "LADY", "name" => "Sarah", "version" => 0, "default" => "My partner Pokémon is the best there is.", "caught" => "I caught a stunning <CAUGHT_POKEMON>. Now it gets to live a life of luxury with us!", "evolved" => "Now that <UNEVOLVED_POKEMON> has evolved, it's even more of itself! More comfortable, more confident, and more beautiful!", "fused" => "This is a fusion with two elegant Pokémon. Together, <HEAD_POKEMON> and <BODY_POKEMON> will show you just how stunning a <FUSED_POKEMON> experience can be!", "unfused" => "I was tired of some of the comments I was getting, so I unfused my precious <UNFUSED_POKEMON>...", "reversed" => "Do you know what the opposite of <UNREVERSED_POKEMON> is? I'll show you!", "gift" => "You should take this with you so you can have a more luxurious life as well. Don't mind the Pokémon hair on it."},
  {"type" => "RICHBOY", "name" => "Dawson", "version" => 0, "default" => "I'm not just doing this for my Pokémon! I'm also fighting for myself!", "caught" => "I spilled my bag filled with Pokédollars earlier, and all the shiny coins attracted this <CAUGHT_POKEMON>.", "evolved" => "I got tired of my <UNEVOLVED_POKEMON> being so weak, so I went to the store and bought a bunch of Rare Candy.", "fused" => "Did you know that Super Splicers make better fusions than regular DNA Splicers?<br>You need to be able to afford them, though.", "unfused" => "If you keep fusing and unfusing, you're gonna run out of DNA Splicers quickly.<br>Not that it matters for someone as rich as me.", "reversed" => "What is the opposite of being rich?<br>Oh no, no, no, I don't even want to think about such a thing!<br>Let me turn my <UNREVERSED_POKEMON> into its opposite instead!", "gift" => "Take this. My bag is so stuffed with Full Restores that it doesn't fit."},
  {"type" => "HIKER", "name" => "Mike", "version" => 0, "default" => "I haven't shown off my Rock Pokémon's full potential!<br>Let's rematch!", "caught" => "My buddy came back with some more mountain Pokémon for me to try.<br>Want to see my <CAUGHT_POKEMON> in action?", "evolved" => "While I wasn't looking, my <UNEVOLVED_POKEMON> evolved into <EVOLVED_POKEMON>!<br>My buddy is never going to believe this!", "fused" => "My buddy told me I should try fusing <HEAD_POKEMON> and <BODY_POKEMON>...<br>Let's see how strong they became!", "unfused" => "The more Pokémon the better, so I told my buddy to unfuse <UNFUSED_POKEMON>!<br>Hopefully my intuition was right!", "reversed" => "My buddy wanted me to reverse <UNREVERSED_POKEMON>!<br><REVERSED_POKEMON> looks ready to fight!", "gift" => "My buddy wanted to give you this as thanks for fighting their Pokémon!"},
  {"type" => "FISHERMAN", "name" => "Ned", "version" => 0, "default" => "If you can't find the Pokémon you're looking for while fishing, try a different spot.", "caught" => "Want to see my newest catch? I'll even allow you to fight it.", "evolved" => "The bigger fish are hard to get out of the water.<br>That's why I catch the small ones and then raise them up.", "fused" => "Fusing Pokémon is like catching two birds with one stone. Or... two fish with one hook?", "unfused" => "My wife laughed at me when I came home with only one catch.<br>But the look on her face when I turned it into two before her eyes was priceless!", "reversed" => "With my <REVERSED_POKEMON>, I will get a cool win!", "gift" => "Sometimes you fish up the weirdest stuff. Can you believe that I had this thing on my hook?"},
  {"type" => "FISHERMAN", "name" => "Elliot", "version" => 0, "default" => "Let's have a- Agh! Pleh! I got feathers in my mouth!<br>You know what I mean, right?", "caught" => "Maybe the Wingull won't bother my new <CAUGHT_POKEMON>...", "evolved" => "Ever since my <UNEVOLVED_POKEMON> evolved, the Wingull have been pestering us more than ever!", "fused" => "Oop! That Wingull knocked my DNA Splicer away! Wait, did my <HEAD_POKEMON> and <BODY_POKEMON> fuse?", "unfused" => "Maybe the Wingull are doing this because my Pokémon are fused. I'll try unfusing my <UNFUSED_POKEMON> and see if that helps at all...", "reversed" => "Maybe if I reverse my Pokémon, the Wingull won't recognize them anymore.", "gift" => "AAHKYAW! Oh, I've been around these Wingull so much that even my sneezes are starting to sound like them.<br>Here, maybe if you take this, they'll follow you and leave me alone."},
  {"type" => "CRUSHGIRL", "name" => "Laura", "version" => 0, "default" => "Hiyiahh! My head keeps spinning! Is that normal?", "caught" => "My motto is \"Don't think and just do!\"<br>When I saw this <CAUGHT_POKEMON>, I just caught it.", "evolved" => "My <EVOLVED_POKEMON> evolved!<br>This wouldn't have been possible if we had wasted time overthinking it!", "fused" => "I fused my Pokémon.<br>Why did I do it? Dunno, I didn't think about it.", "unfused" => "I unfused my Pokémon.<br>Why did I do it? Dunno, I didn't think about it.", "reversed" => "I reversed my fusion.<br>Why did I do it? Dunno, I didn't think about it.", "gift" => "Don't think. Just take it.<br>Hiyiahh! In the name of friendship!"},
  {"type" => "CRUSHGIRL", "name" => "Lilith", "version" => 0, "default" => "My Pokémon might be blind, but that just enhances its other senses!", "caught" => "My new <CAUGHT_POKEMON> is ready to train with me!", "evolved" => "Yeeeha! My <EVOLVED_POKEMON> got so much stronger after honing both body and mind!", "fused" => "Do you think combining two Pokémon also doubles the size of their mind?", "unfused" => "To gain strength, you need to grow in numbers.<br>That is one of the drawbacks of Pokémon fusions.", "reversed" => "Maybe my <REVERSED_POKEMON> can see better now that <HEAD_POKEMON> took the helm.", "gift" => "This is my favorite item. But by giving it to you, I will strengthen my mind and willpower."},
  {"type" => "SAILOR", "name" => "Brendan", "version" => 0, "default" => "Did you know that some rodent Pokémon can swim across the ocean?<br>I think that's how they populated some of the islands.", "caught" => "This <CAUGHT_POKEMON> looked lost as it drifted across the ocean, so I took it in.", "evolved" => "If my <EVOLVED_POKEMON> keeps growing like this, it will soon rule over the seven seas!", "fused" => "The place where two oceans meet is called a marine convergence zone.<br>Allow me to show you my Pokémon convergence zone!", "unfused" => "Sometimes the ocean currents make you drift apart.<br>My <UNFUSED_POKEMON> were hit by one such current, it seems.", "reversed" => "The ebb and flow... Two total opposites...<br>Just like my <REVERSED_POKEMON>.", "gift" => "I found this at the beach earlier. I wonder who it belonged to..."},
  {"type" => "BLACKBELT", "name" => "Cristian", "version" => 0, "default" => "My pincers are still ready for battle!", "caught" => "I caught a <CAUGHT_POKEMON>! It'll do in a pinch!", "evolved" => "A-ha! My <UNEVOLVED_POKEMON> evolved! Now we can defeat you chop-chop!", "fused" => "I pinched my <HEAD_POKEMON> and <BODY_POKEMON> together to discover a new species for battle!", "unfused" => "Now that my <UNFUSED_POKEMON> has come apart, we can use the ultimate pincer maneuver on you!", "reversed" => "My Pokémon pinched a DNA Reverser from me! Now look at it!", "gift" => "Always take advice with a pinch of salt.<br>What? You don't want any salt? Fine, take this instead."},
  {"type" => "CRUSHGIRL", "name" => "Jocelyn", "version" => 0, "default" => "Meditation is also a type of training.<br>Want me to show you how it is done?", "caught" => "While I was meditating, a <CAUGHT_POKEMON> came by and joined me.<br>Now it is always by my side.", "evolved" => "My <EVOLVED_POKEMON> evolved while we were meditating.<br>I only noticed when I opened my eyes again.", "fused" => "Someone threw a DNA Splicer at my <HEAD_POKEMON> and <BODY_POKEMON> while we were meditating...<br>I bet it was Brawly... He always tries to mess with us during our training.", "unfused" => "To master meditation means to master adaptability. That's why I decided to unfuse my Pokémon and give them a challenge.", "reversed" => "To master meditation means to master adaptability. That's why I decided to reverse my fusion and give it a challenge.", "gift" => "Ah, my meditation partner!<br>I have a present for you, as a token of my appreciation."},
  {"type" => "BLACKBELT", "name" => "Takao", "version" => 0, "default" => "Training make muscles bigger. It is known.", "caught" => "New partner is like new fist. It is known.", "evolved" => "Evolved partner is like bigger fist. It is known.", "fused" => "Fused partner is like double fist. It is known.", "unfused" => "Unfused partner is like two fists. It is known.", "reversed" => "Reversed partner is like using other fist. It is known.", "gift" => "Thing is known. Here is thing."},
  {"type" => "LEADER_Brawly", "name" => "Brawly", "version" => 0, "default" => "Do you want to train with me before you go on?", "caught" => "Last time I went surfing, I wiped out next to this <CAUGHT_POKEMON>. It seemed pretty eager to fight, so I took it onto my team!", "evolved" => "My Pokémon evolved, and its strength is totally gnarly! Let's see if you can beat this!", "fused" => "This is a mondo strong fusion. My <HEAD_POKEMON> and <BODY_POKEMON> fused after training hard!", "unfused" => "I discovered the secret of true power by staring at a Helix Fossil for days and days... I unfused my <UNFUSED_POKEMON> so we could have more eyes on it at a time.", "reversed" => "I took my Pokémon surfing, and we did a tubular kickflip together. When we got back on shore, I saw that my <UNREVERSED_POKEMON> had reversed!<br>Did someone drop a DNA Reverser in the water?", "gift" => "I kept this from my old training sessions in Kanto with a good friend of mine there. I think you'll make better use of it, though."},
  {"type" => "SAILOR", "name" => "Huey", "version" => 0, "default" => "In the best port was the best Trainer. No surprise here!", "caught" => "I've sailed around the world, but the <CAUGHT_POKEMON> around Slateport City are something else. I just had to catch one!", "evolved" => "It's so easy to evolve Pokémon while you're in Slateport City. I think it's the sea air that does it. Check it out!", "fused" => "Ah! One of the best things about traveling is fusing your Pokémon with some of the local ones, like I just did. Check it out!", "unfused" => "After traveling to many ports, I've learned that sometimes a fusion works better in one place than other. <UNFUSED_POKEMON> will be better unfused.", "reversed" => "You gotta be prepared for anything when you sail the seas! Always keep a DNA Reverser handy to reverse Pokémon when you need to.", "gift" => "<PLAYER_NAME>! I brought this back from my travels. I think you should have it!"},
  {"type" => "TUBER_M", "name" => "Ricky", "version" => 0, "default" => "How about if I beat you in a rematch, you owe me a Soda Pop!", "caught" => "I caught a <CAUGHT_POKEMON> all by myself! You gotta give IT a Soda Pop, too, now!", "evolved" => "Woohoo! <UNEVOLVED_POKEMON> evolved! You should give me a Soda Pop to celebrate!", "fused" => "Okay.. Will you finally give me that Soda Pop if I fuse two of my Pokémon?<br>No? Well, too late!", "unfused" => "Fine... If you won't give me a Soda Pop, then I'll unfuse <UNFUSED_POKEMON>. That's on you!", "reversed" => "Here, <UNREVERSED_POKEMON>. Have a sip of Soda Pop...<br>Oh, snap! That was a DNA Reverser!", "gift" => "Let's do a trade! I'll give you this if you promise to give me a Soda Pop in exchange!"},
  {"type" => "SAILOR", "name" => "Edmond", "version" => 0, "default" => "I'm usually stronger than this! I was just seasick as a dog!<br>I'm feeling a bit better now, though, so what do you say?", "caught" => "Urrrpp... I found a <CAUGHT_POKEMON> washed up earlier... Thought it was seashells at first.", "evolved" => "Urghh... <UNEVOLVED_POKEMON> evolved to keep me safe while I'm sick.", "fused" => "Urrppp... Do you think it would help me feel better if I fused <HEAD_POKEMON> and <BODY_POKEMON>?", "unfused" => "Did <UNFUSED_POKEMON> unfuse? Urghh.. I'm so sick that I can't keep up with my own Pokémon.", "reversed" => "Urrpp... Is it my head spinning, or did <UNREVERSED_POKEMON> reverse itself?", "gift" => "Urppp... I found this on the beach, but I can't stand looking at it while I'm sick. Please take it!"},
  {"type" => "TUBER_F", "name" => "Hailey", "version" => 0, "default" => "When I have an inner tube, me and my Pokémon's cuteness goes way up! I'll prove it to you!", "caught" => "Look at this <CAUGHT_POKEMON> I caught! I should get it its own tube!", "evolved" => "Uh-oh! <UNEVOLVED_POKEMON> is gonna need a bigger tube now that it evolved!", "fused" => "<HEAD_POKEMON> and <BODY_POKEMON> both wanted to go on the same tube.<br>They fused together so that they would fit!", "unfused" => "<UNFUSED_POKEMON> fell off its tube and unfused!", "reversed" => "Woops! <UNREVERSED_POKEMON> flipped its tube upside down while playing in the waves! Looks like the fusion flipped too!", "gift" => "Mommy gave me this... But I don't want it, so take it!"},
  {"type" => "TUBER_F", "name" => "Lola", "version" => 0, "default" => "We'll be the king and queen of the castle, but you can be a servant.", "caught" => "I found another servant for our castle! It's a <CAUGHT_POKEMON>!", "evolved" => "Woah! <UNEVOLVED_POKEMON> evolved!<br>It's no longer a servant; now it's royalty like me!", "fused" => "Servant, look at this! Two of my Pokémon fused together!", "unfused" => "We need more servants for the castle! Let's unfuse <UNFUSED_POKEMON>!", "reversed" => "I commanded <UNREVERSED_POKEMON> to reverse itself! Royal servants must obey!", "gift" => "You've been a loyal servant to the king and I. You deserve a royal reward!"},
  {"type" => "TUBER_M", "name" => "Chandler", "version" => 0, "default" => "It's okay if the castle gets taken by the waves; building the castle is the most fun part!", "caught" => "Huh? There was a <CAUGHT_POKEMON> inside the castle this whole time!", "evolved" => "Our sandcastle is taking so long to make that <UNEVOLVED_POKEMON> had the time to evolve!", "fused" => "Maybe if I fuse <HEAD_POKEMON> with <BODY_POKEMON>, it'll be better at guarding the castle.", "unfused" => "I need more guards for the castle!<br>I know, I'll just unfuse <UNFUSED_POKEMON>!", "reversed" => "I reversed <UNREVERSED_POKEMON>, but now it's guarding the wrong side of the castle!", "gift" => "Hey! I found this inside the castle... You can have it!"},
  {"type" => "SAILOR", "name" => "Dwayne", "version" => 0, "default" => "I'm always up for another fight, sailor! Want to give it a go?", "caught" => "I'm always up for another fight, sailor! Want to give it a go?", "evolved" => "I gave <UNEVOLVED_POKEMON> a sip of my Soda Pop and it evolved! Coincidence? I think not!", "fused" => "I fused my Pokémon, and now I'm ready to head out to sea again!", "unfused" => "<UNFUSED_POKEMON> is now unfused. Two crewmates are better than one!", "reversed" => "<UNREVERSED_POKEMON> drank too many Soda Pops and got confused. Now it's a <REVERSED_POKEMON>!", "gift" => "Here, sailor! This is no Soda Pop, but it'll do!"},
  {"type" => "BEAUTY", "name" => "Johanna", "version" => 0, "default" => "Another battle? Sure, just let me take a quick sip first!", "caught" => "<CAUGHT_POKEMON> joined my team! It must've been attracted by all the Soda Pops I've been drinking!", "evolved" => "Oh? <UNEVOLVED_POKEMON> evolved? It must be because of the the fresh sea air!", "fused" => "Isn't it neat? I fused <HEAD_POKEMON> with <BODY_POKEMON>. It's like mixing Soda Pop flavors!", "unfused" => "<UNFUSED_POKEMON> wanted more Soda Pop, so it unfused itself to get a second drink. That trickster!", "reversed" => "Uh? Didn't <REVERSED_POKEMON> use to be a <UNREVERSED_POKEMON>?", "gift" => "I tried buying a Soda Pop from the vending machine, but this came out instead!"},
  {"type" => "TUBER_M", "name" => "Simon", "version" => 0, "default" => "Let's fight again! But don't cry if you lose.", "caught" => "I went out and caught a <CAUGHT_POKEMON> on the beach!", "evolved" => "Woah! <UNEVOLVED_POKEMON> is so big now!!", "fused" => "My Pokémon are best friends now, so they decided to fuse!", "unfused" => "Sniff.. I didn't mean to unfuse <UNFUSED_POKEMON>...", "reversed" => "Heehee, I made my Pokémon switch places! They look silly like that!", "gift" => "<PLAYER_NAME>! I've been saving up so that I could get you this."},
  {"type" => "AROMALADY", "name" => "Daisy", "version" => 0, "default" => "Aromatherapy can heal your body and mind.", "caught" => "The scent of a new Pokémon always brings a fresh harmony to the air.<br>Would you like to meet my new friend?", "evolved" => "Ah! <UNEVOLVED_POKEMON>'s aroma has blossomed beautifully!", "fused" => "When two Pokémon blend into one, their fragrances intertwine into something enchanting.", "unfused" => "Unfused again, <HEAD_POKEMON> and <BODY_POKEMON> release distinct aromas.", "reversed" => "A reversed fusion shifts the bouquet entirely. Unexpected, yet delightful.", "gift" => "Every item has its own distinct smell. The fragrance of this one is quite exquisite!"},
  {"type" => "TWIN_1", "name" => "Amy", "version" => 0, "default" => "The two of us together make one! We're better when we battle together!", "caught" => "Liv caught a <CAUGHT_POKEMON> and gave it to me! That's why she's the best sister!", "evolved" => "Look, Liv! <UNEVOLVED_POKEMON> grew up! ", "fused" => "<HEAD_POKEMON> and <BODY_POKEMON> fused together. Now they'll be in sync just like Liv and I!", "unfused" => "<HEAD_POKEMON> and <BODY_POKEMON> don't need to be fused to be in sync! Look!", "reversed" => "Reversing a fusion changes everything. Liv says it's like a whole new strategy!", "gift" => "I found this for you. Liv wanted to keep it for us, but I think you should have it!"},
  {"type" => "TWIN_2", "name" => "Liv", "version" => 0, "default" => "If I could fuse with my sister, I would!!", "caught" => "I caught a <CAUGHT_POKEMON>. Now, I just need to find another one for my sister.", "evolved" => "Look, Amy! <UNEVOLVED_POKEMON> grew up! ", "fused" => "Amy likes to fuse Pokémon, so I did the same with <HEAD_POKEMON> and <BODY_POKEMON>!", "unfused" => "Uh-oh! <HEAD_POKEMON> and <BODY_POKEMON> are out of sync now!", "reversed" => "Reversing fusions? It's like a mirror battle! Amy and I love it!", "gift" => "I found this for you. Amy wanted to keep it for us, but I think you should have it!"},
  {"type" => "POKEFAN_M", "name" => "Miguel", "version" => 0, "default" => "You simply gotta come out and look in on my delightful Pokémon again!", "caught" => "I came across a delightful <CAUGHT_POKEMON>!<br>It might be even more adorable than my other Pokémon. Just look at it!", "evolved" => "Oh, my! <UNEVOLVED_POKEMON> evolved! How delightful!", "fused" => "Do you think that <HEAD_POKEMON> would be even more delightful if it were fused with <BODY_POKEMON>? There's only one way to find out!", "unfused" => "No! <HEAD_POKEMON> and <BODY_POKEMON> are simply too delightful to be combined together. They're more adorable separately.", "reversed" => "I figured out how to make <UNREVERSED_POKEMON> even more delightful. All I had to do was to reverse it!", "gift" => "I found this adooooorable item. I thought of you as soon as I saw it!"},
  {"type" => "FISHERMAN", "name" => "Andrew", "version" => 0, "default" => "Gah, I'm still boiling mad... Grrr....", "caught" => "Aughhh!! I got attacked by a <CAUGHT_POKEMON> while I was trying to fix my line!", "evolved" => "Gahhh! My <UNEVOLVED_POKEMON> evolved... I don't have time for this!", "fused" => "Gahhh! <BODY_POKEMON> and <HEAD_POKEMON> got tangled up too!", "unfused" => "Okay... I untangled <BODY_POKEMON> and <HEAD_POKEMON>... Now to do the same with my fishing line.", "reversed" => "Aughh... I tried to untangle <UNREVERSED_POKEMON>, but it's even more tangled than before!", "gift" => "Arghh! This got stuck in my fishing line. Take it!"},
  {"type" => "ROCKER", "name" => "Marcos", "version" => 0, "default" => "My one-man show is ruined. I need to practice more!", "caught" => "I got a new member in my band. Wanna check us out?", "evolved" => "Woah! My <UNEVOLVED_POKEMON> evolved! What kind of tunes can it play now?", "fused" => "I fused <HEAD_POKEMON> and <BODY_POKEMON>. They'll be my new rhythm section!", "unfused" => "Check this out: <HEAD_POKEMON> and <BODY_POKEMON> can play even more notes unfused!", "reversed" => "My Pokémon swapped instruments... We'll have a whole new sound!", "gift" => "I found this while I was rocking out. You can have it!"},
  {"type" => "BLACKBELT", "name" => "Rhett", "version" => 0, "default" => "You gotta make sure you're prepared if you're gonna sneak up on someone.", "caught" => "Woah! A <CAUGHT_POKEMON> sneaked up on me!", "evolved" => "Woah! One of my Pokémon just evolved out of nowhere!", "fused" => "Hahah! I sneaked up on my Pokémon and fused them!", "unfused" => "Hahah! I sneaked up on my <UNFUSED_POKEMON> and unfused it!", "reversed" => "Woah! My Pokémon reversed themselves while I wasn't looking!", "gift" => "Woah! This item came out of nowhere! Take it!"},
  {"type" => "POKEFAN_F", "name" => "Isabel", "version" => 0, "default" => "My Pokémon became even cuter. Allow me to show them off.", "caught" => "Take a look at my newest cutie! But be warned, it packs quite a punch too!", "evolved" => "Most Pokémon lose some of their cuteness when they evolve.<br>Not the case with my <EVOLVED_POKEMON>!", "fused" => "I experimented with more fusions in the name of cuteness.<br>This is the result!", "unfused" => "I have realized that cuteness is related to simpleness.<br>That is why I have decided to unfuse my <UNFUSED_POKEMON> again.", "reversed" => "Maybe the other way around is cuter? Hmm...<br>I need a second opinion here. Help me out.", "gift" => "My adorable Pokémon found this for me.<br>But I already have one, so you can have it."},
  {"type" => "COLLECTOR", "name" => "Edwin", "version" => 0, "default" => "Do you want to see my cute Pokémon again?", "caught" => "I ran into a Pokémon in the tall grass, and it was so cute that I just had to catch it!", "evolved" => "Oh, wow, I had no idea that my <EVOLVED_POKEMON> was able to evolve!", "fused" => "Alright, alright. I gave in. I decided to try this fusion thing as well.", "unfused" => "In the end, nothing can convince me that my Pokémon aren't cute enough as they are.", "reversed" => "Oops, I wanted to unfuse my <HEAD_POKEMON>, but I accidentally bought a DNA Reverser.", "gift" => "Sharing purifies your character, and a pure character is essential for something to be cute.<br>N-no, I didn't just make that up!"},
  {"type" => "YOUNGSTER", "name" => "Timmy", "version" => 0, "default" => "Being cool also means never giving up!<br>My Pokémon are ready to go again! Rematch me!", "caught" => "This <CAUGHT_POKEMON> I caught is just the coolest!<br>I'll prove it to you in a fight!", "evolved" => "My <UNEVOLVED_POKEMON> evolved!<br>I couldn't believe they could become even cooler!", "fused" => "Fusing two cool Pokémon together will surely make a super cool Pokémon!<br>Let me show off what <FUSED_POKEMON> can do!", "unfused" => "Sometimes unfused Pokémon are cooler; that's why I unfused my <UNFUSED_POKEMON>...", "reversed" => "I tried using this DNA Reverser a friend gave to me, and now my Pokémon looks even cooler!", "gift" => "Thanks for showing me so many cool fusions! Here, have this!"},
  {"type" => "PSYCHIC_M", "name" => "Edward", "version" => 0, "default" => "Ah, it's you. Erm... I forgot your name.<br>Can you show me your Trainer Card again?<br>What, only if I can beat you in battle?<br>Fine... bring it on!", "caught" => "He he he... I heard that my new <CAUGHT_POKEMON> has the power to read your mind!<br>With its help, I will find out what your name is!", "evolved" => "The offer still stands, right? If I can win, you will tell me your name!", "fused" => "I spent my last Pokédollar on this DNA Splicer.<br>I better be able to win this time!", "unfused" => "I'm really getting desperate here.<br>If only I had actual psychic powers...", "reversed" => "<PLAYER_NAME>! It was totally <PLAYER_NAME>!<br>I finally remembered! Let's celebrate with another battle!", "gift" => "Here, will you show me your Trainer Card again if I give you this?"},
  {"type" => "FISHERMAN", "name" => "Dale", "version" => 0, "default" => "Fishing is all about concentration. You have to focus on the bobber.", "caught" => "My bobber took the plunge! Now I've got a <CAUGHT_POKEMON>!", "evolved" => "I thought my Pokémon went down, but it bobbed back up with Evolution!", "fused" => "I fused my Pokémon while fishing. I wasn't really looking, though, so I don't know which ones I fused.", "unfused" => "My Pokémon wouldn't stop pestering me while I was trying to keep my eye on the bobber. I unfused it in the hopes that it would stop.", "reversed" => "In honor of my new bobber, I reversed my <UNREVERSED_POKEMON>. Do you think it looks more like a bobber now?", "gift" => "I have the grandest gift I can give you: A bobber!<br>You seem disappointed. All right, take this instead."},
  {"type" => "BEAUTY", "name" => "Melissa", "version" => 0, "default" => "__", "caught" => "__", "evolved" => "__", "fused" => "__", "unfused" => "__", "reversed" => "__", "gift" => "__"},
  {"type" => "ROCKER", "name" => "Joseph", "version" => 0, "default" => "I'm still looking for my Pokémon that was stolen by that bird Pokémon...", "caught" => "I miss my <CAUGHT_POKEMON> so much that I caught a new one, but it's just not the same...", "evolved" => "I must grow stronger, so that I am able to take revenge on that stealing bird Pokémon if it ever dares to show up here again!", "fused" => "I need to know how good my new fusion is against bird Pokémon.<br>Can you help me out?", "unfused" => "I plan to use my <UNFUSED_POKEMON> as bait to lure out that stealing bird Pokémon!", "reversed" => "What is this?! Something is in my other pocket!<br>Did I never lose that Poké Ball at all?!<br>...<br>No... That's just a DNA Reverser...", "gift" => "Can you do me a favor?<br>If you ever see that stealing bird Pokémon, can you throw this at it?"},
  {"type" => "TRIATHLETE_BIKE_F", "name" => "Alyssa", "version" => 0, "default" => "Do you want another match? Okay, but only muscle power allowed!", "caught" => "This <CAUGHT_POKEMON> outran me on my bike!<br>I was so impressed that I asked it to join my team.", "evolved" => "Oh no, my <EVOLVED_POKEMON> evolved, and now it no longer fits into my bike...", "fused" => "There isn't much room to carry things on a bike.<br>That's why you have to cut weight wherever possible.", "unfused" => "My <UNFUSED_POKEMON> and I were eating protein bars, but it accidentally bit into a DNA Splicer...", "reversed" => "It's time to reverse gears!", "gift" => "Can you hold onto this for me? It's weighing me down."},
  {"type" => "PSYCHIC_F", "name" => "Jaclyn", "version" => 0, "default" => "If we practice together, perhaps I can cultivate special powers in you as well.", "caught" => "When I reached out into the realm of thoughts, <CAUGHT_POKEMON> responded. We found each other and are stronger together.", "evolved" => "My <UNEVOLVED_POKEMON> evolved. Clearly this is because of the special powers we've wielded in our training!", "fused" => "The memories of my <HEAD_POKEMON>... The memories of my <BODY_POKEMON>...<br>They have come together to create something new!", "unfused" => "I unfused my <UNFUSED_POKEMON> so that I could read the thoughts of each of its halves separately.<br>Using my special powers, I've gained a greater understanding of my Pokémon!", "reversed" => "Using my special powers, I read your thoughts. You wanted a different sort of battle. That's why I reversed my <UNREVERSED_POKEMON>!", "gift" => "I sense you have made progress in your training. No, don't say anything. Thoughts are enough. Take this."},
  {"type" => "TRIATHLETE_BIKE_F", "name" => "Abigail", "version" => 0, "default" => "What does ERS stand for? Eat, relieve, sleep, of course!", "caught" => "Grab, throw, catch. I used this GTC-Cycle to capture my newest team member!", "evolved" => "Learn, grow, evolve. That's the LGE-Cycle.", "fused" => "Buy, touch, splice. It's the BTS-Cycle.", "unfused" => "Change mind, touch, unsplice. If you want to unfuse your Pokémon, you need to follow the CTU-Cycle.", "reversed" => "Today is a weird day. Instead of following the ERS-Cycle, I accidentally did an SRE-Cycle...", "gift" => "I like coming up with names. Here, you can have this 'Unique Utility Device'."},
  {"type" => "TRIATHLETE_BIKE_M", "name" => "Anthony", "version" => 0, "default" => "Sorry, sometimes I say nasty things when I lose...", "caught" => "I threw a Poké Ball at a wild <CAUGHT_POKEMON> with so much force that it got knocked out.", "evolved" => "I was angry and got into a brawl with my <UNEVOLVED_POKEMON>, but then it evolved and knocked me out!", "fused" => "My <HEAD_POKEMON> and <BODY_POKEMON> didn't get along, so I fused them together. He he he...", "unfused" => "The best part about love is the pain when you inevitably get torn apart!", "reversed" => "Fine, I'll tell you the truth.<br>When I was young, I stepped onto my Stunfisk. Totally flattened the thing.<br>It was never the same afterwards.", "gift" => "I want to apologize about some of the things I said earlier.<br>Here, I hope this will make up for it."},
  {"type" => "TRIATHLETE_BIKE_M", "name" => "Benjamin", "version" => 0, "default" => "We triathletes help each other out. How can I help you?", "caught" => "A <CAUGHT_POKEMON> is the perfect partner for a triathlon, don't you agree?", "evolved" => "Look at the strong legs of my <EVOLVED_POKEMON>!", "fused" => "My <FUSED_POKEMON> can dive for five minutes straight!", "unfused" => "<UNFUSED_POKEMON> carries my water bottles while I race!", "reversed" => "Are your Pokémon faster than mine?<br>Let me warn you, I have optimized the speed of my team!", "gift" => "Never go on a triathlon without one of these!"},
  {"type" => "TRIATHLETE_BIKE_F", "name" => "Jasmine", "version" => 0, "default" => "Bring it on! I use my fourth gear!", "caught" => "My crew is getting bigger. All that is missing now is a musician.", "evolved" => "Fufufu, I went through a timeskip since the last time you were here!", "fused" => "Look at my secret technique! Pokémon Docking: Big Emperor!", "unfused" => "I lost my <UNFUSED_POKEMON>, but I still have my crew!", "reversed" => "Fufufu, check out my new secret power! Gear negative five!", "gift" => "This is my treasure, but I'll let you hold it."},
  {"type" => "TRIATHLETE_BIKE_M", "name" => "Jacob", "version" => 0, "default" => "Bike racing can be dangerous. Make sure you're using your brakes before you battle me again.", "caught" => "This <CAUGHT_POKEMON> totally crashed into my bike earlier. It's much safer for it to be in my Poké Ball!", "evolved" => "My Pokémon evolved with a blinding flash of light during my last race! I swear, that's the only reason I lost!", "fused" => "When my brakes failed, my DNA Splicer went flying out of my pocket! <BODY_POKEMON> doesn't look the same anymore...", "unfused" => "I unfused my <UNFUSED_POKEMON> so I could have more competitors to race against. Do you know anyone who can tailor helmets to fit Pokémon?", "reversed" => "I tried to turn too sharply and got turned around. My Pokémon seems turned around too!", "gift" => "Yikes! Watch where you're going with that bike! Oh, I dropped that at your feet, but I guess you can keep it."},
  {"type" => "CRUSHGIRL", "name" => "Aisha", "version" => 0, "default" => "I'm concentrating on training.", "caught" => "I concentrated on catching a Pokémon. That's how I found a <CAUGHT_POKEMON>!", "evolved" => "After all of our training, my <UNEVOLVED_POKEMON> evolved. We're not done training yet, though!", "fused" => "I fused my <HEAD_POKEMON> and <BODY_POKEMON> using the sheer power of my focus!<br>Also, with DNA Splicers!", "unfused" => "After deep concentration, I realized that having more Pokémon on my team will help me win. That's why I unfused <UNFUSED_POKEMON>!", "reversed" => "Before you use DNA Reversers, you have to concentrate. Concentrate on the ideal fusion!", "gift" => "You've been a good sparring partner! I wanted to get you a gift, so after concentrating my energy on deciding, I chose this for you!"},
  {"type" => "TRIATHLETE_RUN_F", "name" => "Melina", "version" => 0, "default" => "I like triathlons because you get to see different scenery while competing. It's just like Pokémon battles in that way!", "caught" => "This cute Pokémon started running beside me while I was heading through the meadow. We're friends now!", "evolved" => "My Pokémon's Evolution was even more stunning with all the flower petals blowing around! Actually, it was sort of an intense experience.", "fused" => "While we were running through the flowers, my <HEAD_POKEMON> and <BODY_POKEMON> ran away from me. I miss them very much, but at least I met this <FUSED_POKEMON> shortly after!", "unfused" => "I unfused my Pokémon to take some pictures of them in the flowers. I'll probably fuse them back again after our run.", "reversed" => "I used to come out and run through the flowers with my favorite Pokémon all the time when I was younger. Reversing my <UNREVERSED_POKEMON> reminded me of that.", "gift" => "I made you a flower crown, but wildflowers wilt so quickly. Perhaps this can make up for your original present falling apart."},
  {"type" => "SCHOOLMATE_JR", "name" => "Anna", "version" => 0, "default" => "The mysterious Trainer approached me, their feet scuffing quietly on the ground. Why did they seek me out? A skirmish? A parley?", "caught" => "<CAUGHT_POKEMON>'s spirit burned fiercely as it took its place by my side. Now that we had joined forces, no foe could stand in our way.", "evolved" => "A dazzling light! My eyes watered both from the sight of it and from emotion. My dear partner, <UNEVOLVED_POKEMON>, had evolved at last.", "fused" => "All the challenges that <HEAD_POKEMON> had faced... Every triumph that <BODY_POKEMON> had won...<br>They stood combined before me, ready to claim honor on the battlefield once more.", "unfused" => "I had forgotten where I came from! I knew what I had to do. With trembling hands, I held the DNA Splicer...", "reversed" => "A reversal of fate. An ending undone? With my Pokémon's fusion changed, I had a new road before me.", "gift" => "The melodious whizz of my bag's zipper opening preceded the gift's appearance.<br>\"I want you to have this,\" I said to the Trainer."},
  {"type" => "SCHOOLMATE_SR", "name" => "Meg", "version" => 0, "default" => "As an upperclassman, I have to set an excellent example.<br>So, can you at least make me look good by losing a battle?", "caught" => "I caught this <CAUGHT_POKEMON> while Anna was messing around. Don't worry, I'm still keeping an eye on my underclassman!", "evolved" => "Now that <UNEVOLVED_POKEMON> evolved, it needs to set a good example for the rest of the team.", "fused" => "I fused my <HEAD_POKEMON> to show this underclassman how to fuse Pokémon. I don't think she was paying attention, though...", "unfused" => "My Pokémon got into my items and unfused when I wasn't looking! How am I supposed to deal with this and my underclassman at the same time?", "reversed" => "I'm supposed to write my report on fusing Pokémon, but I accidentally grabbed a DNA Reverser instead of a DNA Splicer!", "gift" => "Battling with you has been a lot more fun than studying for my language arts class. If I give you this, will you come by again?"},
  {"type" => "TRIATHLETE_RUN_M", "name" => "Dylan", "version" => 0, "default" => "Let's... Pokéathlon!", "caught" => "I celebrated the Pokéathlon by adding another Pokémon to my team!", "evolved" => "My <UNEVOLVED_POKEMON> evolved! Do you think that will get us more points in the next Pokéathlon?", "fused" => "Pokéathletes these days are all about fusion! I fused my Pokémon so I can keep up with everyone else!", "unfused" => "I unfused my Pokémon so I can be my own team!<br>Ruby, Sapphire, and Emerald are already taken for names, so maybe <HEAD_POKEMON>, <BODY_POKEMON>, and I will be Team Topaz.", "reversed" => "I heard they're planning on building a dome just for the Pokéathlon over in Johto. I reversed my <UNREVERSED_POKEMON> so we can be ready for when it opens.", "gift" => "I'd share my Aprijuice with you, but I need it to train my Pokémon for the Pokéathlon. You can take this instead, though!"},
  {"type" => "POKEMONBREEDER_F", "name" => "Lydia", "version" => 0, "default" => "My Pokémon were inspired to become stronger after fighting you!<br>Wanna see their progress?", "caught" => "Good to see you again. I have bred even more Pokémon.<br>Can you help me with their training?", "evolved" => "My little ones are growing up so fast! Here, let me show you!", "fused" => "I'm running out of space on my team again, so I did some more fusing.<br>I hope my little ones aren't mad at me...", "unfused" => "My <UNFUSED_POKEMON> wasn't very happy about being fused.<br>As a parental figure, sometimes you have to accept your mistakes.", "reversed" => "Have you ever tried reversing your fusions?<br>Who knows, doing that might just be the key to unlocking their full potential!", "gift" => "I have a little something for you, as a thanks for helping me raise my little ones."},
  {"type" => "TRIATHLETE_RUN_F", "name" => "Maria", "version" => 0, "default" => "You appear to be training properly... If you'd like, I'll battle you again!", "caught" => "I caught this <CAUGHT_POKEMON> by running after it! It was no match for my speed!", "evolved" => "Now that my <UNEVOLVED_POKEMON> evolved, I wonder if I'll be able to keep pace with it during training...", "fused" => "It's hard to focus on training multiple Pokémon while I'm trying to train myself for the next triathlon. It's easier to plan our practices now that they're fused into <FUSED_POKEMON>!", "unfused" => "I wasn't sure if my Pokémon was fast because of its <HEAD_POKEMON> side or its <BODY_POKEMON> side. Now that I've unfused it, we can find out!", "reversed" => "Different shapes of Pokémon are better in different kinds of terrain. I reversed my Pokémon so we can go run in new places.", "gift" => "If you beat me in a game of tag, I'll give you a reward!<br>...<br>I didn't say to start yet. Oh well, I guess you win. Go ahead and take this."},
  {"type" => "BUGMANIAC", "name" => "Derek", "version" => 0, "default" => "I was once a Bug Catcher, and now I'm a Bug Maniac!<br>However, my love for Pokémon remains unchanged!", "caught" => "I used my years of experience catching Bug-type Pokémon to help me find this <CAUGHT_POKEMON>. Go, my <CAUGHT_POKEMON>!", "evolved" => "My Pokémon has evolved, just as I have! Even if we seem different, I'll prove we're the same on the inside!", "fused" => "Fusion can lead to growth. My Bug-type Pokémon and I-<br>Wait, are they still Bug types?", "unfused" => "I unfused my <UNFUSED_POKEMON>. Now my swarm will show you how great Bug-type Pokémon are!", "reversed" => "I won't stop discovering as many species of Bug-type Pokémon as I can. That's why I reversed my <UNREVERSED_POKEMON>!", "gift" => "I can tell you also love Bug-type Pokémon. Take this, from one Bug Maniac to another."},
  {"type" => "POKEMONBREEDER_M", "name" => "Isaac", "version" => 0, "default" => "I'm going to redouble my training. Would you come look in on us?", "caught" => "I always have such a hard time choosing which Pokémon to train. I couldn't help myself and took on another one!", "evolved" => "My <UNEVOLVED_POKEMON> evolved, and it's all thanks to the battles you've been having with me!", "fused" => "I fused <HEAD_POKEMON> and <BODY_POKEMON> so that I could train both of them at once!", "unfused" => "<UNFUSED_POKEMON> has been a handful, so I unfused it so I can deal with each of its needs one at a time.", "reversed" => "I wanted to catch new Pokémon, but I don't have much room for more of them. That's why I reversed my <UNREVERSED_POKEMON>'s fusion instead.", "gift" => "My Pokémon woke me up early this morning and gave me this. I'm guessing they wanted you to have it as thanks for helping them grow."},
  {"type" => "AROMALADY", "name" => "Rose", "version" => 0, "default" => "I still believe that the aroma of flowers has a magical power. That's why I use scented oils on my Pokémon!", "caught" => "<CAUGHT_POKEMON> came over to me after smelling the aroma I was wearing. This is proof that flower aroma has magic power!", "evolved" => "My <UNEVOLVED_POKEMON> evolved! If I figure out what combination of oils I put on it, maybe I can sell that as an Evolution fragrance!", "fused" => "Sniff... That odor- It's a Pokédex! Are you trying to find new species? You must see this Pokémon I just fused!", "unfused" => "I don't think my <UNFUSED_POKEMON> liked the fragrance I was using... It unfused and the two Pokémon ran off in different directions! I managed to get them to come back, though.", "reversed" => "My Pokémon has absorbed all kinds of beautiful scents since it reversed to the opposite fusion species. Perhaps <REVERSED_POKEMON> are especially potent with flower power!", "gift" => "I tried putting flower-scented oils on this, but something went wrong. It's giving me a sinus headache, so please take it. Maybe it will help you instead."},
  {"type" => "YOUNGSTER", "name" => "Deandre", "version" => 0, "default" => "Your Pokémon said you're good at making them stronger! Let's battle again!", "caught" => "<CAUGHT_POKEMON> said it was lonely, so I offered to be its friend. What's with that skeptical look?", "evolved" => "<EVOLVED_POKEMON> doesn't say the same things that it said when it was <UNEVOLVED_POKEMON>. Hey, do you think I'm making this up?", "fused" => "My Pokémon asked to be fused together. I wonder why they'd want that. No, it wasn't my idea at all!", "unfused" => "Sometimes I have a hard time understanding what my fused Pokémon say, so I unfused my <UNFUSED_POKEMON>. I'm not just making excuses!", "reversed" => "I thought that <REVERSED_POKEMON> would be the same as it was before reversing, but it talks like it has a different personality! I'm not lying! I never lie!", "gift" => "You at least believe me a little when I say I can understand Pokémon, right? Even if you don't, I think your Pokémon believes me, so please give it this."},
  {"type" => "FISHERMAN", "name" => "Wade", "version" => 0, "default" => "It's wonderful to see Pokémon that are raised with so much heart. Can I see them again?", "caught" => "I caught this <CAUGHT_POKEMON>, but it doesn't really trust me yet. Loving relationships of any kind take time.", "evolved" => "I'm so proud! My <UNEVOLVED_POKEMON> evolved!", "fused" => "It's up to a Trainer to decide when to use a DNA Splicer. Make sure you always have your Pokémon's best interests at heart.", "unfused" => "Ever since I unfused my <UNFUSED_POKEMON>, my <HEAD_POKEMON> and <BODY_POKEMON> help by holding my fishing equipment while I work. They're so kind!", "reversed" => "My Pokémon changed, and I'm still getting used to it. I'm trying to be understanding, but maybe you can show me how through a battle?", "gift" => "Remember! Strength isn't what makes a great Trainer. If you're bad at battling but you love your Pokémon, that makes you a winner!<br>Remember that when you use this!"},
  {"type" => "ROCKER", "name" => "Dalton", "version" => 0, "default" => "Are you telling me that the winner of a Pokémon battle isn't actually supposed to take the loser's Pokémon? Wait, let's try this again!", "caught" => "My new <CAUGHT_POKEMON> and I are gonna play you a rockin' tune!<br>No, I didn't steal it!", "evolved" => "Did my Pokémon really evolve? This kind of thing never happened in Team Rocket!", "fused" => "My <HEAD_POKEMON> and <BODY_POKEMON> came together to make something new. Just like how this ex-grunt and music came together to rock you!", "unfused" => "I almost tried to steal from someone again, but my Pokémon unfused so they could gang up on me!", "reversed" => "My <UNREVERSED_POKEMON> reversed and totally changed. Just like my Pokémon, I can sing a different tune!", "gift" => "You treated me as Dalton the Rocker rather than some nameless grunt. I want you to have this. I got it from... somewhere."},
  {"type" => "ROCKER", "name" => "Kirk", "version" => 0, "default" => "My voice needs a warm up, and my Pokémon are ready to go! Want to fight?", "caught" => "This Pokémon was drawn in by my music, and now it wants to battle! Oh yeah!", "evolved" => "The vocal and battle warm-ups we have been doing made <UNEVOLVED_POKEMON> evolve!<br>Want to see what it's capable of?", "fused" => "<HEAD_POKEMON>'s and <BODY_POKEMON>'s duet potential is just too good to leave them unfused! Yeaa-ah-ah!", "unfused" => "<HEAD_POKEMON> is at its best as a solo. <BODY_POKEMON> was only bringing it down!", "reversed" => "Sometimes you need a sharp change of tune in a song. I think it's time to reverse <UNREVERSED_POKEMON>! Oh-oh-yeaa!", "gift" => "Thanks a lot for letting me test out my performance. Here's something for my biggest fan!"},
  {"type" => "YOUNGSTER", "name" => "Ben", "version" => 0, "default" => "I asked my teacher what a fuse box does, but they keep telling me it would \"shock me\".<br>I'm a big kid, I can handle the suprise. I swear! Just tell me what it does!", "caught" => "I heard that you could find a fuse box in basements, but instead I found a wild Pokémon. Weird!", "evolved" => "When my <UNEVOLVED_POKEMON> evolved, its power made up some crazy wind!<br>Is this what it means to \"blow a fuse\"?", "fused" => "I fused my <FUSED_POKEMON> just like a fuse box would!<br>Huh? You're saying it doesn't do that? Liar!", "unfused" => "I unfused my Pokémon, so I can use a fuse box. After all, you can't fuse already fused Pokémon!", "reversed" => "I thought I had finally gotten my hands on a fuse box, and I used it!<br>...But it was just a DNA Reverser, phooey!", "gift" => "I have a gift for you that you can't \"re-fuse\"<br>Huh? It's pronounced \"refuse\"? Oh, whatever - just take this!."},
  {"type" => "CRUSHGIRL", "name" => "Vivian", "version" => 0, "default" => "My charm doesn't need improvement, but I'm sure my Pokémon may use some battle experience.<br>Let's rematch!", "caught" => "My charms just got me a new Pokémon. I knew I still got it!<br>Let's check out how good it is!", "evolved" => "I was shocked when I found my <UNEVOLVED_POKEMON> had evolved!<br>What did it evolve into? Let me show you! ", "fused" => "Fusing my charm and my Pokémon's power is not enough, so I'm going to fuse <HEAD_POKEMON> and <BODY_POKEMON>. Want to see the results?", "unfused" => "I wasn't electrified about <UNFUSED_POKEMON>'s ability in battle... Maybe unfusing it is for the better?", "reversed" => "I just realized my Pokémon's shock potential will be even better if it reversed! Do you want to try it with me?", "gift" => "I did say my charm is a big asset of mine, didn't I? Here, have this gift!"},
  {"type" => "ROCKER", "name" => "Shawn", "version" => 0, "default" => "I think I know a new strategy.<br>I hope this works!", "caught" => "I gener- I mean, caught a new Pokemon. <br>Lemme see if this one is strong enough.", "evolved" => "I got some Rare Candies and my <UNEVOLVED_POKEMON> evolved!<br>Yes, they are legit... <br>Look, let us just battle.", "fused" => "I changed my team a bit like that one Pokemon Champion guy does!", "unfused" => "I needed to reorganize my team a little bit, so I had to unfuse some things.", "reversed" => "I found out I had one of those Reverser thingies in my bag, so I used that to make my team more dynamic.", "gift" => "I got this item that fell out of favor, and I do not want it anymore. <br>So here, take this."},
  {"type" => "BUGMANIAC", "name" => "Angelo", "version" => 0, "default" => "You already know everything there is to know about me.<br>All I can offer you now is another rematch.", "caught" => "There is something new to know about me! I have a new Pokémon!", "evolved" => "My <UNEVOLVED_POKEMON> has evolved, and I decided to follow suit!", "fused" => "I was overwhelmed with my number of Pokémon, so I fused some of them together.", "unfused" => "Let me tell you everything there is to know about my <UNFUSED_POKEMON>!", "reversed" => "Reversing your Pokémon can have huge consequences, so really think it through first!", "gift" => "I want to give this to you so that a piece of me is always with you."},
  {"type" => "LEADER_Wattson", "name" => "Wattson", "version" => 0, "default" => "I swell with optimism, seeing a promising young Trainer like you!", "caught" => "A <CAUGHT_POKEMON> wandered in here and got stuck because of the door traps, poor thing. I designed my gym for youthful Trainers like you, not wild Pokémon!<br>Well, you don't need to worry about the Pokémon. It's not wild anymore, if you know what I mean!", "evolved" => "Shocking! Electrifying! Wahahahah! My <UNEVOLVED_POKEMON> just evolved!<br>It fills me with energy, watching my Pokémon grow up alongside the Trainers that battle here!", "fused" => "Fusing Pokémon is a little bit like engineering. You decide which parts are best for each other, and then you combine them to create something electrifying! Wahahahah!", "unfused" => "My Pokémon help me with repairing the traps in my Gym. <UNFUSED_POKEMON> unfused to help with two different rigged doors at once, so don't be surprised if you see a <BODY_POKEMON> or a <HEAD_POKEMON> running around!", "reversed" => "Our batteries ran dry, so to speak. I reversed <UNREVERSED_POKEMON> to change things up!", "gift" => "Wahahahah! All right, youngster, you've got my approval! I look forward to more big things from you in the future! Now, take this!"},
  {"type" => "CAMPER", "name" => "Tyron", "version" => 0, "default" => "I'm thinking about more ways to go camping on a budget.", "caught" => "I caught this <CAUGHT_POKEMON> when it was sneaking up on my tent!<br>Always stay alert when sleeping outside!", "evolved" => "My <UNEVOLVED_POKEMON> evolved!<br>Now it can carry more stuff for me!", "fused" => "Have you heard of a spork? It's a fusion between a spoon and a fork! It's kind of like my Pokémon, in a way.", "unfused" => "My spork broke! Now it's back to being a spoon and a fork... Like my Pokémon...", "reversed" => "Look! I turned my spork into a foroon!", "gift" => "When traveling on a budget, you don't want to carry anything you don't need.<br>Here, you can have this."},
  {"type" => "AROMALADY", "name" => "Celina", "version" => 0, "default" => "What even is an Aroma Lady, you ask?<br> Let me give you another demonstration; maybe then you will understand!", "caught" => "A <CAUGHT_POKEMON> was attracted to my smell and now it won't leave my side anymore.", "evolved" => "When I put on my new perfume, my <UNEVOLVED_POKEMON> evolved.", "fused" => "Today I tried putting on two perfumes at the same time.<br>The combined smell is mesmerizing.", "unfused" => "Even with no perfume at all, I still smell very nice.", "reversed" => "I have a cold today and I can't smell well.<br>Please tell me I still smell nice?", "gift" => "Would you buy my perfume?<br>It's not on sale yet, but here is a bonus for early customers."},
  {"type" => "LASS", "name" => "Bianca", "version" => 0, "default" => "Munch, munch, munch. Hm? Did you want something?", "caught" => "I have a tendency to drop food out of my sandwich when I walk. It led this <CAUGHT_POKEMON> right to me!", "evolved" => "I gave my <UNEVOLVED_POKEMON> a sandwich, and then it evolved! What're in these sandwiches?", "fused" => "I took a sip of my tea before having a bite of my sandwich, and that made it even tastier!<br>Wait, that gives me an idea! Let me use this DNA Splicer before we do anything!", "unfused" => "Ugh, there's onions in my sandwich. I've got to take it apart to improve it.<br>Wait, that gives me an idea! Let me use this DNA Splicer first!", "reversed" => "What's the reverse of a sandwich? It's a chiwdnas! No, that's not right. It's a salad? Uhhh, well, the reverse of my <UNREVERSED_POKEMON> is a <REVERSED_POKEMON>!", "gift" => "I stand here and eat a sandwich every day. You see some crazy stuff that way.<br>Here, this went flying past me once. Since it didn't land in my sandwich, you can have it."},
  {"type" => "CAMPER", "name" => "Hayden", "version" => 0, "default" => "Just who keeps stealing all of my snacks?!<br>Do you think a Pokémon is behind this?", "caught" => "I thought this <CAUGHT_POKEMON> was behind the disappearance of my snacks.<br>But no, they keep vanishing.", "evolved" => "I found some slices of onion on the ground, but I decided to feed them to my <UNEVOLVED_POKEMON> instead.<br>You won't believe what happened next!", "fused" => "There wasn't enough food left to feed all of my Pokémon, so I had to reduce the number of mouths to feed... <br>Don't worry, I just fused two of my Pokémon!", "unfused" => "My <UNFUSED_POKEMON> was so hungry that it tried to eat a DNA Splicer...", "reversed" => "My stomach is so empty, it's about to underflow and turn into a positive value.", "gift" => "Please, just give me something to eat! I'll even give you this!"},
  {"type" => "POKEFAN_M", "name" => "Victor", "version" => 0, "default" => "You've come for another battle? Well maybe this one will be my \"Victor\"-y, heh heh!", "caught" => "Holy leaping Linoone in the land of Littleroot! I caught a new Pokémon, and now it's time to battle with it!", "evolved" => "Great day in the morning! I guess I've gotten a bit stronger!<br>I must have if my <UNEVOLVED_POKEMON> evolved!", "fused" => "Well, would you look at that! I used a DNA Splicer, and now my Pokémon is combined like a troubling thicket of Tangela on a Tuesday evening!", "unfused" => "When I was your age, all this \"fusion\" stuff wasn't a thing.<br>It's for sure great and all, but I like to unfuse sometimes for the nostalgia...", "reversed" => "My boy makes me proud; he's off on his own journey carving his own path like a Sandslash through soil!<br>Doesn't mean I can't try to improve myself!! Go, DNA Reverser!!", "gift" => "That was a good battle! Shame I lost again, though.<br>A victory like that deserves a prize, so here this is yours!"},
  {"type" => "POKEFAN_F", "name" => "Victoria", "version" => 0, "default" => "It's nice of you to visit again for another battle, dearie.<br>I'll be sure to give it my all!", "caught" => "I've been a bit of an empty nester since my son left, so I caught a new Pokémon to help keep me company. Let's show them what for, <CAUGHT_POKEMON>!", "evolved" => "My little cutie of a <UNEVOLVED_POKEMON> evolved! I guess I can't really call it little anymore though...", "fused" => "I'm happy I still get to battle as much as I do at this age! Yet, all this fusion stuff, well...<br>It sometimes reminds me of our honeymoon...", "unfused" => "My <FUSED_POKEMON> was being a bit bratty, so I had to put it in \"timeout\" for a bit by unfusing it.<br>Hopefully this battle will help clear their minds!", "reversed" => "I try to keep my home nice and full of \"feng shui\". I try to do same with my Pokémon as well, but it hasn't felt right....<br>Maybe reversing a fusion on my team will fix that feeling right up!", "gift" => "Our son is off on his own journey. It makes a mother worry...<br>You remind me a lot of him, so take this."},
  {"type" => "LASS", "name" => "Vivi", "version" => 0, "default" => "You've come for another battle? Great!<br>If we keep battling, eventually I'll be as strong as my brother Vito!", "caught" => "I caught another Pokémon!<br>I'm one step closer to being the best in the family!", "evolved" => "Hey! Did you know?<br>Did you know that my Pokémon have gotten stronger and evolved since last time we've battled?<br>Now you know!", "fused" => "I called my brother and asked him for some advice. He recommended fusing my <HEAD_POKEMON> and <BODY_POKEMON> together!<br>Let's see if he was right!", "unfused" => "A good Trainer knows when to take a step back and re-strategize their team.<br>That's why I unfused my <UNFUSED_POKEMON>!", "reversed" => "I wanted to mix things up, so I used a DNA Reverser. My dad could learn a thing or two from that.<br>I'm getting sidetracked! Let's battle!", "gift" => "I lost ag-gain, sniffle... B-but I'll keep improving, so thanks!<br>I think you should have this!"},
  {"type" => "EXPERT_F", "name" => "Vicky", "version" => 0, "default" => "I haven't forgiven you for making my granddaughter cry!<br>I'll beat you senseless!", "caught" => "This 97-year-old granny can still catch Pokémon the old-fashioned way! Hwah!", "evolved" => "My <UNEVOLVED_POKEMON> evolved, and let me tell you...<br>My son could learn a' thing or two from that, keh he!", "fused" => "When fusing Pokémon, some think about power or looks...<br>... But that's all nonsense! I just wanted an excuse to spoil 'em! Kwah ha!", "unfused" => "I taught my grandson nearly everything he knows about battling!<br>So, you shouldn't be surprised either that I know when to unfuse my Pokémon!", "reversed" => "These old eyes of mine... I had meant to use a Splicer, but instead I used a Reverser. Oh well!", "gift" => "Keh he he! You've been spending a lot more time with us Winstrates than you have to!<br>Here, take this."},
  {"type" => "LASS", "name" => "Irene", "version" => 0, "default" => "__", "caught" => "__", "evolved" => "__", "fused" => "__", "unfused" => "__", "reversed" => "__", "gift" => "__"},
